let lang = 'en';
export const getLang = () => lang;
export const langTag = (id = lang) => (LANGS.find((l) => l.id === id) || LANGS[0]).tag;
export const langName = (id = lang) => (LANGS.find((l) => l.id === id) || LANGS[0]).name;
export function setLang(id) { lang = LANGS.some((l) => l.id === id) ? id : 'en'; }
// The phone's own language, if we have it (else English).
export function defaultLang() {
  const n = String((typeof navigator !== 'undefined' && navigator.language) || 'en').slice(0, 2).toLowerCase();
  return n === 'od' ? 'or' : LANGS.some((l) => l.id === n) ? n : 'en';
}
// English for the few texts that are keys, not words.
const EN = {
  VOICE_OK: 'Phone voice ready ✓', VOICE_MISSING: 'No voice for this language on this device, so the game stays silent. Add the voice to hear Vikram.',
  STORY_NOTE: '', VOICE_TIP: 'Best voices: the Android app. On PC, the Edge browser has natural voices for all these languages.', 'FREE ROAM OBJECTIVE': null,
};
export function t(en) {
  if (lang === 'en') return en in EN ? EN[en] : en;
  const row = T[en];
  return row ? row[ORDER.indexOf(lang)] : en;
}
// "NEW SIM ₹500" -> "नई सिम ₹500"
export function tLabel(label) { const m = String(label).match(/^(.*?)(\s*₹.*)?$/); return t(m[1]) + (m[2] || ''); }

// Every fixed text on the page that gets translated: [selector, English, before, mode, after].
// mode '' = the element's text, 'label' = the text of the <label> around an input, 'br' = two lines.
