// The lines for one key in the chosen language (null in English: the game keeps its own lines).
export function spoken(key) { const r = SPOKEN[key]; return r && lang !== 'en' ? r[ORDER.indexOf(lang)] : null; }

// English objective ("go to Ravi's garage") -> a short sentence in the chosen language (names stay as they are).
const RULES = [
  [/^(?:lose|shake off|escape from) (?:the )?(?:police|cops)/i, 'lose'],
  [/^get out of (?:the |your |this )?(?:car|vehicle|truck|van|auto|jeep|taxi|bike)/i, 'getout'],
  [/^(?:get|jump|hop)(?: back)? (?:in|into|inside) (?:the |your |a |any )?(?:car|vehicle|auto|truck|van|jeep|taxi|bike|boat)/i, 'getin'],
  [/^(?:take out|kill|wreck|take down|destroy|defeat|beat|finish|damage|stop) (?:the )?(.+)/i, 'kill'],
  [/^(?:drive|bring|take|deliver|carry) (?:the )?(.+?) (?:to|back to) (?:the )?(.+)/i, 'bring'],
  [/^(?:go|drive|run|walk|head|come|ride|get|race|fly|swim|sail)(?: back)? to (?:the )?(.+)/i, 'go'],
  [/^(?:reach|arrive at|return to) (?:the )?(.+)/i, 'go'],
  [/^(?:steal|grab|pick up|collect|snatch) (?:the )?(.+)/i, 'steal'],
  [/^(?:follow|tail|chase|stay with|keep up with) (?:the )?(.+)/i, 'follow'],
  [/^(?:find|search for|look for|spot) (?:the )?(.+)/i, 'find'],
  [/^(?:protect|escort|defend|guard|save) (?:the )?(.+)/i, 'protect'],
  [/^(?:talk to|meet|speak to|ask) (?:the )?(.+)/i, 'talk'],
  [/^(?:escape|get away|run away|get out)/i, 'escape'],
  [/^(?:deliver|bring) (?:the )?(.+)/i, 'deliver'],
];
function clause(s, i) {
  for (const [re, k] of RULES) {
    const m = s.match(re);
    if (m) return P[k][i].replace('{x}', (m[1] || '').trim()).replace('{y}', (m[2] || '').trim());
  }
  return null;
}
function sentence(x) {
  const i = ORDER.indexOf(lang), s = String(x || '').trim();
  // "get out of the car and talk to Kapoor" -> two short sentences.
  const parts = s.split(/\s+and\s+(?:then\s+)?/i);
  if (parts.length === 2) { const a = clause(parts[0], i), b = clause(parts[1], i); if (a && b) return a + ' ' + b; }
  return clause(s, i) || P.any[i].replace('{x}', s);
}
const pickOf = (a) => a[Math.floor(Math.random() * a.length)];
export function sayObjective(x) { const i = ORDER.indexOf(lang); return i < 0 ? '' : pickOf(OBJ[i]).replace('{s}', sentence(x)); }
export function sayReminder(x) { const i = ORDER.indexOf(lang); return i < 0 ? '' : pickOf(REMIND[i]).replace('{s}', sentence(x)); }
export function sayGreeting() { const i = ORDER.indexOf(lang); return i < 0 ? '' : pickOf(GREET[i]); }
